@import url('https://fonts.googleapis.com/css2?family=Fugaz+One&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Borussia Dortmund DNA — the yellow wall itself, black punch */
.theme-dortmund {
  --bg: oklch(0.891 0.183 96.2);
  --surface: oklch(0.910 0.174 98.8);
  --surface-2: oklch(0.861 0.177 95.6);
  --fg: oklch(0.178 0 0);
  --fg-muted: oklch(0.438 0.088 101.8);
  --accent: oklch(0.178 0 0);
  --accent-fg: oklch(0.891 0.183 96.2);
  --accent-2: oklch(0.420 0.010 270.0);
  --line: oklch(0.178 0 0);
  --success: oklch(0.523 0.135 144.2);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.25rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: none;
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Fugaz One", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-dortmund h1,
.theme-dortmund h2,
.theme-dortmund h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-dortmund { --font-ui: var(--font-display); }
.theme-dortmund h1, .theme-dortmund h2 { text-transform: uppercase; }
.theme-dortmund button { text-transform: uppercase; letter-spacing: 0.06em; }

.theme-dortmund { background-image: repeating-linear-gradient(0deg, oklch(0 0 0 / 4%) 0 3px, transparent 3px 90px); }
.theme-dortmund h1 { -webkit-text-stroke: 2px #111111; color: var(--bg); font-size: clamp(3.2rem, 7vw, 6rem) !important; }
.theme-dortmund button { border: 2px solid #111111; }

/* depth */
.theme-dortmund thead th { background: var(--accent); color: var(--accent-fg); text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.78em; }
.theme-dortmund td { border-bottom: 1px solid oklch(0.178 0 0 / 30%); }
.theme-dortmund tbody tr:hover { background: oklch(0 0 0 / 8%); }
.theme-dortmund a { color: var(--fg); text-decoration-thickness: 3px; text-underline-offset: 3px; }
/* terrace chant: hover flips to full black block */
.theme-dortmund a:hover { background: var(--accent); color: var(--accent-fg); text-decoration: none; }
.theme-dortmund ::selection { background: oklch(0.178 0 0); color: oklch(0.891 0.183 96.2); }
.theme-dortmund input, .theme-dortmund select, .theme-dortmund textarea { border: 2px solid oklch(0.178 0 0); background: oklch(0.95 0.09 98); }
.theme-dortmund input:focus-visible, .theme-dortmund select:focus-visible, .theme-dortmund textarea:focus-visible { outline: 3px solid oklch(0.178 0 0); outline-offset: 2px; }
.theme-dortmund kbd { background: oklch(0.178 0 0); color: oklch(0.891 0.183 96.2); border-radius: var(--radius-sm); padding: 0.1em 0.5em; font-family: var(--font-mono); font-weight: 700; }
.theme-dortmund ::-webkit-scrollbar { width: 12px; height: 12px; }
.theme-dortmund ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-dortmund ::-webkit-scrollbar-thumb { background: oklch(0.178 0 0); border-radius: 2px; }
.theme-dortmund ::-webkit-scrollbar-thumb:hover { background: oklch(0.30 0 0); }
.theme-dortmund .label-caps { background: oklch(0.178 0 0); color: oklch(0.891 0.183 96.2); padding: 0.15em 0.5em; }
/* hazard tape: the Südtribüne barrier */
.theme-dortmund .themed-border { border-image: repeating-linear-gradient(45deg, oklch(0.178 0 0) 0 12px, oklch(0.891 0.183 96.2) 12px 24px) 1; border-width: 3px; }
.theme-dortmund button:active { transform: translate(1px, 2px); }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-dortmund.alt-mode {
  --bg: oklch(0.209 0.006 271.1);
  --surface: oklch(0.243 0.008 264.4);
  --surface-2: oklch(0.277 0.010 268.3);
  --fg: oklch(0.932 0.003 286.3);
  --fg-muted: oklch(0.673 0.008 268.5);
  --accent: oklch(0.891 0.183 96.2);
  --accent-fg: oklch(0.191 0 0);
  --accent-2: oklch(1.000 0 0);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  background-image: repeating-linear-gradient(135deg, oklch(0.3 0.005 260 / 60%) 0 6px, transparent 6px 12px, oklch(0.25 0.005 260 / 40%) 12px 30px, transparent 30px 60px);
}
.theme-dortmund.alt-mode input, .theme-dortmund.alt-mode select, .theme-dortmund.alt-mode textarea { background: oklch(0.185 0.005 271); border-color: oklch(0.891 0.183 96.2); color: var(--fg); }
.theme-dortmund.alt-mode input:focus-visible, .theme-dortmund.alt-mode select:focus-visible, .theme-dortmund.alt-mode textarea:focus-visible { outline-color: oklch(0.891 0.183 96.2); }
.theme-dortmund.alt-mode td { border-bottom-color: oklch(1 0 0 / 15%); }
.theme-dortmund.alt-mode tbody tr:hover { background: oklch(1 0 0 / 7%); }
.theme-dortmund.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.891 0.183 96.2); }
.theme-dortmund.alt-mode ::-webkit-scrollbar-thumb:hover { background: oklch(0.95 0.16 98); }
.theme-dortmund.alt-mode h1 { -webkit-text-stroke: 0; color: #ffd900; }
.theme-dortmund.alt-mode h2, .theme-dortmund.alt-mode h3 { color: #ffd900; }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
